    >>> two_sum([2,7,11,15], 9)
    (0, 1)
    """
    seen = {}
    for i, num in enumerate(nums):
        diff = target - num
        if diff in seen:
            return (seen[diff], i)
        seen[num] = i
    return (-1, -1)


